-- Hand-written aerospace Deep Cases, days 1-6 (18 cases, three per day).
-- Each case shares its brief, evidence and numbers across learner goals and holds a final call
-- and debrief for every goal (career, invest, build_startup, curiosity).
-- Safe to run more than once: creates public.deep_cases if missing and upserts each case.
BEGIN;

CREATE TABLE IF NOT EXISTS public.deep_cases (
  id UUID PRIMARY KEY,
  market_id TEXT NOT NULL REFERENCES public.markets(id),
  day INTEGER NOT NULL CHECK (day BETWEEN 1 AND 365),
  slot SMALLINT NOT NULL CHECK (slot BETWEEN 1 AND 3),
  content JSONB NOT NULL,
  tags TEXT[] NOT NULL DEFAULT ARRAY['handwritten-v1']::text[],
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  UNIQUE (market_id, day, slot)
);

GRANT SELECT ON public.deep_cases TO authenticated;
GRANT ALL ON public.deep_cases TO service_role;
ALTER TABLE public.deep_cases ENABLE ROW LEVEL SECURITY;

DO $$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_policies WHERE schemaname = 'public' AND tablename = 'deep_cases'
                 AND policyname = 'Deep cases readable by signed-in learners') THEN
    CREATE POLICY "Deep cases readable by signed-in learners" ON public.deep_cases FOR SELECT TO authenticated USING (true);
  END IF;
END $$;

CREATE INDEX IF NOT EXISTS idx_deep_cases_market_day ON public.deep_cases (market_id, day);

INSERT INTO public.deep_cases (id, market_id, day, slot, content, tags) VALUES
($ml$922b73ef-3598-584b-a148-50775ff42212$ml$::uuid, $ml$aerospace$ml$, 1, 1, $ml${"id": "aerospace-d1-c1", "title": "Who builds a Dreamliner?", "lessonTitle": "Who really builds an airliner", "slot": 1, "type": "apply", "brief": {"headline": "About 35% of the Boeing 787's airframe is built by Japanese companies. Boeing's name is on the plane, but its wing box comes from Mitsubishi Heavy Industries.", "kicker": "Apply the map: who is the OEM here, and who is Tier 1?", "fullText": "Japanese companies build about 35% of the 787's airframe. Mitsubishi Heavy Industries makes the main wing box. Kawasaki Heavy Industries builds part of the forward fuselage, the main landing gear wheel well and the wing's fixed trailing edge. Fuji Heavy Industries makes the center wing box and joins it to the wheel well.\n\nBoeing designs the plane, joins these big structures, installs the systems and gets each aircraft approved. That makes Boeing the OEM. Companies that hand it whole structures or systems sit at Tier 1, and the repair shops that keep 787s flying later are the MRO layer.", "sources": [{"url": "https://www.globalsecurity.org/military/world/japan/b787.htm", "label": "GlobalSecurity, Japan and the Boeing 787"}, {"url": "https://blog.brennaninc.com/what-are-the-three-tiers-in-the-aerospace-supply-chain", "label": "Brennan, aerospace supply chain tiers"}, {"url": "https://www.faa.gov/newsroom/how-it-works-aircraft-certification", "label": "FAA, How aircraft certification works"}]}, "evidence": {"kind": "sortSignal", "prompt": "Sort each company by its place on the 787's map.", "buckets": ["OEM", "Tier 1", "MRO"], "items": [{"text": "Boeing, which joins the structures and gets each plane approved", "bucket": 0}, {"text": "Mitsubishi Heavy Industries, maker of the main wing box", "bucket": 1}, {"text": "Fuji Heavy Industries, maker of the center wing box", "bucket": 1}, {"text": "Kawasaki Heavy Industries, maker of the wheel well", "bucket": 1}, {"text": "Lufthansa Technik, which overhauls airliners for airlines", "bucket": 2}, {"text": "AAR, an independent airframe repair shop", "bucket": 2}], "explanation": "Boeing designs, assembles and certifies, so it is the OEM. The Japanese firms hand Boeing whole structures, which is Tier 1 work. Lufthansa Technik and AAR keep planes flying after delivery."}, "numbers": {"kind": "numberSense", "prompt": "What share of the 787's airframe do Japanese companies build?", "min": 0, "max": 100, "value": 35, "unit": "%", "explanation": "About 35%. The name on the tail is Boeing, but a third of the structure is made in Japan."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You're interviewing at Mitsubishi Heavy Industries' aircraft unit. They ask how you would describe its role on the 787.", "prompt": "Which answer shows you know the map?", "options": ["The OEM, since it builds the 787 wings", "An MRO shop that services 787 wings", "A Tier 1 partner building the 787 wing box"], "correctIndex": 2, "consequences": ["The OEM signs for the whole plane; building wings does not make you one.", "MRO comes after delivery, and this team builds new structure.", "You place the company precisely, which is what they listen for."], "explanation": "Mitsubishi delivers a whole structure straight to Boeing. That is Tier 1 work, and Boeing remains the OEM."}, "proReasoning": "A strong candidate names the layer and the product in one breath: Tier 1, 787 wing box. It shows you know who the customer is and what a late delivery would stop.", "commonMistake": "Calling any big builder the OEM. The OEM is the company whose name is on the plane and who gets it approved.", "mentalModel": "Name the layer, the product and the customer."}, "invest": {"call": {"kind": "theCall", "situation": "You follow two stocks: Boeing and a Japanese firm that builds 787 structures. Boeing announces it will build fewer 787s next year.", "prompt": "Whose revenue does the slower build rate hit?", "options": ["Both, since the supplier is paid per plane", "Only Boeing, since its name is on the plane", "Only the supplier, since Boeing is paid early"], "correctIndex": 0, "consequences": ["Fewer planes built means fewer wing boxes bought.", "The supplier builds to Boeing's rate, so its sales fall too.", "Boeing collects most of its cash at delivery, so it is hit as well."], "explanation": "A Tier 1 sells one set of parts for each plane built. When Boeing slows the line, the supplier's sales slow with it."}, "proReasoning": "Investors trace a program's build rate down the tiers. A rate cut at the OEM shows up in the sales of every supplier on that program.", "commonMistake": "Treating suppliers as independent of the OEM. On one program, they rise and fall together.", "mentalModel": "Suppliers live on the OEM's build rate."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your startup has a tool that inspects carbon fiber wing parts faster. You need a first customer on the 787.", "prompt": "Who do you pitch first?", "options": ["Lessors that own the most 787s", "The Tier 1 that builds the wing box", "Airlines that fly and maintain the 787"], "correctIndex": 1, "consequences": ["Lessors own the jets but never touch production.", "You pitch the team that inspects those parts every day.", "Airlines maintain planes; they do not build wing boxes."], "explanation": "A tool for inspecting new wing parts sells to whoever makes them. On the 787, that is the Tier 1 building the wing box."}, "proReasoning": "Founders find the buyer by asking who does the job the tool improves. New wing parts are inspected at the Tier 1, so that is the door to knock on.", "commonMistake": "Pitching the biggest name in the chain. The OEM or the airline may be far from the problem you solve.", "mentalModel": "Sell to whoever does the work your product improves."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend says the 787 is an all-American plane because Boeing builds it.", "prompt": "What's the more accurate picture?", "options": ["Boeing builds nearly every part itself", "Japan builds it and Boeing adds its name", "Boeing assembles it from parts built worldwide"], "correctIndex": 2, "consequences": ["The main wing box and center wing box come from Japanese firms.", "Boeing joins the plane and gets it approved, which is the OEM job.", "About 35% of the airframe is built in Japan alone."], "explanation": "Boeing designs, assembles and certifies the 787. Big pieces, including the wing box, come from suppliers abroad."}, "proReasoning": "Ask who designs, who builds which part and who signs for the whole. One airliner usually has several countries inside it.", "commonMistake": "Assuming the name on the tail built the whole plane.", "mentalModel": "The name on the tail is the integrator, not the only builder."}}}$ml$::jsonb, ARRAY['handwritten-v1']::text[]),
($ml$9bfd6a06-3401-5c3e-91ec-947e5984bc02$ml$::uuid, $ml$aerospace$ml$, 1, 2, $ml${"id": "aerospace-d1-c2", "title": "One engine, three layers", "lessonTitle": "Who really builds an airliner", "slot": 2, "type": "connect", "brief": {"headline": "Every Boeing 737 MAX flies on engines built by CFM, not by Boeing. Years later, the overhaul may be done by the airline, by CFM or by an independent shop.", "kicker": "Connect the layers: one engine passes through all three.", "fullText": "CFM International builds the LEAP-1B, the only engine offered on the 737 MAX. It sells the engines for Boeing to hang on the wing. Boeing assembles the plane, gets it approved and delivers it. That makes CFM a Tier 1 supplier and Boeing the OEM.\n\nOnce the plane is flying, the engine needs maintenance, repair and overhaul, or MRO. Airlines, engine makers and independent shops all do this work: airline-owned shops such as Lufthansa Technik, and independents such as AAR. One engine touches every layer of the map.", "sources": [{"url": "https://www.cfmaeroengines.com/about", "label": "CFM International"}, {"url": "https://planefyi.com/guides/aircraft-comparison/a320neo-vs-737max/", "label": "PlaneFYI, A320neo vs 737 MAX"}, {"url": "https://blog.brennaninc.com/what-are-the-three-tiers-in-the-aerospace-supply-chain", "label": "Brennan, aerospace supply chain tiers"}, {"url": "https://report.lufthansagroup.com/2025/annual-report/en/combined-management-report/business-segments/mro-business-segment/", "label": "Lufthansa Group annual report 2025, MRO"}, {"url": "https://www.aarcorp.com/aar-named-to-top-10-airframe-mros-in-the-world-by-aviation-week/?pg=4", "label": "AAR"}]}, "evidence": {"kind": "buildChain", "prompt": "Follow one 737 MAX engine from the factory to its first overhaul.", "steps": ["CFM builds a LEAP-1B engine", "Boeing hangs it on a new 737 MAX", "Boeing delivers the plane to an airline", "The airline flies it for years", "An MRO shop overhauls the engine"], "explanation": "The engine starts at a Tier 1, flies under the OEM's name, and returns to the MRO layer for upkeep."}, "numbers": {"kind": "numberSense", "prompt": "An airline flies 40 Boeing 737 MAX jets. How many CFM engines are on their wings?", "min": 0, "max": 200, "value": 80, "explanation": "Two per jet: 80 engines, not counting spares. Each one will need overhauls for as long as it flies."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You're applying to CFM. The recruiter asks who your team's customers would be.", "prompt": "Which answer fits CFM's place on the map?", "options": ["OEMs buy our engines, airlines our service", "Airlines buy complete airliners from us", "Passengers pay us through ticket prices"], "correctIndex": 0, "consequences": ["You show both sides of the business: the sale and the upkeep.", "CFM builds engines; the OEM builds and delivers the airliner.", "Tickets pay the airline, not the engine maker."], "explanation": "CFM sells engines for OEMs like Boeing and Airbus to install. Once the planes fly, airlines also pay for engine upkeep."}, "proReasoning": "A good answer names two customers: the OEM at the sale and the airline afterward. Engine makers live on both.", "commonMistake": "Naming only the OEM and forgetting the years of service that follow.", "mentalModel": "Engine makers serve the OEM first and the airline for years."}, "invest": {"call": {"kind": "theCall", "situation": "You compare three companies: an OEM, an engine maker and an independent MRO shop. Airlines decide to keep older jets flying longer.", "prompt": "Which business benefits most directly?", "options": ["None, since only new planes earn money", "The MRO shop that keeps them flying", "The OEM that built them years ago"], "correctIndex": 1, "consequences": ["Upkeep is a business of its own, and older fleets need more of it.", "Older planes need more upkeep, and the MRO shop does that work.", "The OEM got most of its money at delivery and needs new orders."], "explanation": "MRO earns from every year an older plane keeps flying. The OEM earns mostly when a new plane is delivered."}, "proReasoning": "Investors split the chain by when each layer gets paid. OEMs earn at delivery; MRO earns while planes keep flying.", "commonMistake": "Assuming a slowdown in new plane orders hurts every aerospace company equally.", "mentalModel": "Ask when each layer gets paid."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your startup predicts when engine parts will wear out, using flight data. You need a first paying customer.", "prompt": "Which layer runs into that problem every week?", "options": ["Tier 3 makers of small fasteners", "The OEM's final assembly line", "MRO shops that plan engine overhauls"], "correctIndex": 2, "consequences": ["Fastener makers build new parts; they don't track wear.", "Final assembly builds new planes; it doesn't track wear.", "They plan engine shop visits, so better forecasts save them money."], "explanation": "Wear shows up after delivery. MRO shops and the airlines they serve plan around it every week."}, "proReasoning": "Founders match the product to a moment in the plane's life. Wear prediction lives after delivery, in the MRO layer.", "commonMistake": "Selling to the factory a product that only matters once the plane is flying.", "mentalModel": "Match your product to a stage of the plane's life."}, "curiosity": {"call": {"kind": "theCall", "situation": "Your 737 MAX flight is delayed for engine maintenance. A friend asks who is doing the work.", "prompt": "Which answer could be true?", "options": ["The airline, CFM or an independent shop", "Only Boeing, since its name is on the plane", "Only the airport the plane is parked at"], "correctIndex": 0, "consequences": ["All three do MRO work, depending on the airline's contracts.", "Boeing built the plane; upkeep is often done by others.", "Airports run terminals and runways, not engine repairs."], "explanation": "MRO is done by airlines, engine makers and independent shops. The OEM is usually not the one turning the wrenches."}, "proReasoning": "Separate who built a part from who maintains it. They are often different companies.", "commonMistake": "Assuming the OEM fixes the planes it sells.", "mentalModel": "Building and maintaining are different jobs."}}}$ml$::jsonb, ARRAY['handwritten-v1']::text[]),
($ml$0cabd0d2-1b8a-5580-bc38-4502099c21a3$ml$::uuid, $ml$aerospace$ml$, 1, 3, $ml${"id": "aerospace-d1-c3", "title": "The supplier that came home", "lessonTitle": "Who really builds an airliner", "slot": 3, "type": "decide", "brief": {"headline": "In 2005 Boeing sold its Wichita fuselage plant. In December 2025 it bought the Boeing work back, and 737 fuselages still ride a train to Renton.", "kicker": "Decide: what changes when a supplier becomes part of the OEM?", "fullText": "Boeing sold its Wichita division in 2005, and it became Spirit AeroSystems, an outside supplier of 737 fuselages and major structures for the 767, 777 and 787. In December 2025 Boeing completed its purchase of Spirit's Boeing work.\n\nThe trains still roll: fuselages leave Wichita by rail and arrive in Renton, Washington, where the 737 is assembled. What changed is the map. The same factory moved from Tier 1 supplier to part of the OEM.", "sources": [{"url": "https://www.spiritaero.com/company/overview/history/", "label": "Spirit AeroSystems history"}, {"url": "https://boeing.mediaroom.com/2025-12-08-Boeing-Completes-Acquisition-of-Spirit-Aerosystems", "label": "Boeing, Dec 2025"}, {"url": "https://www.railwayage.com/?p=27569", "label": "Railway Age"}]}, "evidence": {"kind": "spotFake", "prompt": "One of these is false after December 2025. Tap it.", "statements": ["Boeing stopped using the Wichita plant after the deal.", "Spirit was a Tier 1 supplier to Boeing before the deal.", "Wichita's Boeing work is now part of the OEM."], "fakeIndex": 0, "explanation": "Boeing bought the Wichita work to keep it, not to close it. The plant moved from Tier 1 to inside the OEM."}, "numbers": {"kind": "numberSense", "prompt": "Boeing sold the Wichita plant in 2005 and bought the work back in 2025. How many years was it an outside supplier?", "min": 0, "max": 50, "value": 20, "unit": "years", "explanation": "Twenty years as Spirit AeroSystems, a Tier 1 supplier, before it came back inside Boeing."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You join Boeing's Wichita team right after the buyback. Your manager asks what your first priority should be.", "prompt": "What do you say?", "options": ["Find new customers for the fuselages", "Learn Boeing's quality rules for the line", "Renegotiate the fuselage price with Boeing"], "correctIndex": 1, "consequences": ["The fuselages are Boeing's own; there's no customer to find.", "The plant now answers directly to the OEM's quality system.", "There's no outside price to haggle over: the plant is Boeing now."], "explanation": "Once the plant is inside the OEM, there's no supplier contract to negotiate. What matters is building to Boeing's own system."}, "proReasoning": "When a supplier becomes part of the OEM, the job changes from selling to Boeing to being Boeing. Quality and process become internal duties.", "commonMistake": "Carrying old supplier habits, like price talks, into a plant that now belongs to the customer.", "mentalModel": "Inside the OEM, the contract becomes a process."}, "invest": {"call": {"kind": "theCall", "situation": "Before the deal, Boeing paid Spirit for each fuselage. Now Boeing owns the Wichita work.", "prompt": "Who carries the cost of a bad fuselage now?", "options": ["Spirit's old shareholders", "Airlines, since they fly the planes", "Boeing, all of it"], "correctIndex": 2, "consequences": ["They sold the Boeing work, and its risks moved with it.", "Airlines suffer the delays, but the cost of fixing lands on Boeing.", "Owning the plant means owning its costs and its mistakes."], "explanation": "When an OEM buys its supplier, the supplier's costs and quality risk become its own."}, "proReasoning": "An investor reads a buyback as a swap: Boeing gains control and takes on the plant's costs and problems. Control is not free.", "commonMistake": "Seeing only the upside of control and forgetting that the losses come with it.", "mentalModel": "Buy the supplier, own its problems."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your startup sold a rivet inspection tool to the Wichita plant in 2024. Now Boeing owns that work.", "prompt": "What should you do first?", "options": ["Get approved as a Boeing supplier", "Keep invoicing Spirit as before", "Switch to pitching airlines instead"], "correctIndex": 0, "consequences": ["Your customer is now the OEM, with its own buying rules.", "Spirit no longer owns that plant's Boeing work.", "Airlines don't inspect rivets on new fuselages."], "explanation": "The plant changed owners, so your customer did too. Boeing's buying rules now decide whether you stay."}, "proReasoning": "Founders watch who owns the factory they sell into. A new owner can mean a new buyer, new approvals and a contract to win again.", "commonMistake": "Assuming a contract survives a change of owner on its own.", "mentalModel": "When the owner changes, win the customer again."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks why Boeing would buy back a factory it sold twenty years earlier.", "prompt": "Which reason fits the story best?", "options": ["Airlines asked Boeing to own the factory", "It needed control of a supplier it couldn't replace", "Railroads raised the cost of moving fuselages"], "correctIndex": 1, "consequences": ["Airlines buy planes, not factories.", "Spirit was losing money, and no one else could build that fuselage soon.", "Rail still carries the fuselages; shipping was not the reason."], "explanation": "Spirit built a part no one else could make soon, and it was struggling. Owning it gave Boeing direct control."}, "proReasoning": "Big companies buy suppliers when depending on them becomes too risky. Control costs money, but losing the part would cost more.", "commonMistake": "Thinking companies only buy what they want to grow; some buy what they cannot lose.", "mentalModel": "Own what you can't afford to lose.", "sources": [{"url": "https://www.manufacturingdive.com/news/spirit-aerosystems-q4-2024-airbus-boeing-supplier-merger-acquisition/741460/", "label": "Manufacturing Dive, Spirit AeroSystems 2024 results"}, {"url": "https://boeing.mediaroom.com/2025-12-08-Boeing-Completes-Acquisition-of-Spirit-Aerosystems", "label": "Boeing, Dec 2025"}]}}}$ml$::jsonb, ARRAY['handwritten-v1']::text[]),
($ml$f4777b6e-ea18-52ea-9065-7006147dc0c3$ml$::uuid, $ml$aerospace$ml$, 2, 1, $ml${"id": "aerospace-d2-c1", "title": "The jets stuck in Russia", "lessonTitle": "How an airliner gets paid for", "slot": 1, "type": "apply", "brief": {"headline": "About 400 leased jets were stuck in Russia after sanctions in 2022. AerCap, a lessor, took a $2.7 billion charge before tax on 113 aircraft it could not recover.", "kicker": "Apply the lesson: when a leased plane is lost, who loses?", "fullText": "After Russia invaded Ukraine in February 2022, Western sanctions forced lessors to end their leases with Russian airlines. About 400 foreign-leased aircraft stayed in Russia anyway.\n\nAerCap had 111 aircraft stranded in Russia and two more in Ukraine. In May 2022 it reported a pre-tax charge of $2.729 billion on 113 aircraft and eleven engines, about $2.4 billion after tax.\n\nLater, some lessors reached settlements over the trapped planes. AerCap agreed one worth $645 million in September 2023 for 17 jets and five spare engines. The airline flies the plane; the lessor owns it, and owns the risk of losing it.", "sources": [{"url": "https://airinsight.com/aercap-takes-2-4-billion-net-charge-on-aircraft-in-russia-and-ukraine/", "label": "AirInsight, AerCap takes $2.4 billion net charge"}, {"url": "https://www.insurancejournal.com/news/international/2024/06/21/780616.htm", "label": "Insurance Journal, lessor settlements over planes in Russia"}, {"url": "https://www.iata.org/en/iata-repository/publications/economic-reports/more-aircraft-are-leased-than-owned-by-airlines-globally", "label": "IATA, more aircraft are leased than owned"}]}, "evidence": {"kind": "faceOff", "prompt": "Who took the loss on the leased jets stranded in Russia?", "left": {"name": "The Russian airlines", "note": "Kept flying the jets"}, "right": {"name": "The lessors", "note": "Owned the jets and could not get them back"}, "correctIndex": 1, "explanation": "The lessor owns the plane. When it can't be recovered, the lessor writes it off."}, "numbers": {"kind": "numberSense", "prompt": "AerCap had 111 of the roughly 400 leased jets stuck in Russia. About what share is that?", "min": 0, "max": 100, "value": 28, "unit": "%", "explanation": "111 out of about 400 is roughly 28%. One lessor held more than a quarter of the stranded fleet."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You're interviewing at an aircraft leasing company. They ask what makes their business different from an airline's.", "prompt": "Which answer shows you get it?", "options": ["We own the jets; the airline flies them", "We fly the jets and sell the tickets", "We build jets and sell them to airlines"], "correctIndex": 0, "consequences": ["Exactly, and when a jet can't come back, the loss is the lessor's.", "That's the airline's job; the lessor rents it the plane.", "That's the OEM; lessors buy from OEMs like any airline."], "explanation": "A lessor owns aircraft and rents them out. Russia showed the other side: the owner carries the loss when a plane is gone."}, "proReasoning": "Good candidates talk about the asset. Lessors earn rent but carry the plane's value, and its risk, through every lease.", "commonMistake": "Describing a lessor as a bank. It owns the plane outright and must place it with the next airline.", "mentalModel": "Lessors earn rent and own the risk."}, "invest": {"call": {"kind": "theCall", "situation": "You hold shares in a lessor. Many of its jets fly for airlines in one country that faces new sanctions.", "prompt": "What's the biggest risk to watch?", "options": ["The airlines repainting the jets", "Getting the jets back at all", "Monthly rent arriving a bit late"], "correctIndex": 1, "consequences": ["Paint is cheap; a lost jet is not.", "AerCap took a $2.7 billion charge when it could not.", "Late rent hurts, but losing the plane costs far more."], "explanation": "A lessor's value sits in its planes. If they can't be recovered, it writes off the asset, as AerCap did in 2022."}, "proReasoning": "Investors check where a lessor's jets fly. Too many in one risky country can turn rent into a write-off.", "commonMistake": "Watching the rent and ignoring whether the asset can be taken back.", "mentalModel": "A lessor is worth what it can get back."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your startup keeps aircraft records ready so a jet can move quickly from one airline to the next. Lessors are interested.", "prompt": "Why would a lessor pay for that?", "options": ["It needs help selling airline tickets", "It wants to design aircraft of its own", "Its jets change airlines many times"], "correctIndex": 2, "consequences": ["Lessors don't sell tickets; airlines do.", "Lessors buy from OEMs; they don't design planes.", "Every handover needs complete records, and gaps cost time and rent."], "explanation": "A lessor owns a plane across many leases. Anything that speeds the move between airlines keeps it earning."}, "proReasoning": "Founders look for the moments a business loses money. For a lessor, a plane sitting idle between leases earns nothing.", "commonMistake": "Pitching a lessor like an airline. It doesn't fly or sell tickets; it owns and places planes.", "mentalModel": "Find where the owner's asset sits idle."}, "curiosity": {"call": {"kind": "theCall", "situation": "News says Russian airlines still fly jets that belong to foreign companies.", "prompt": "How can an airline fly a plane it doesn't own?", "options": ["It leased the plane from a lessor", "It bought the plane on credit", "It borrowed the plane from the OEM"], "correctIndex": 0, "consequences": ["58% of the world's fleet was leased at the end of 2023.", "Buying on credit means the airline owns it, and leasing does not.", "OEMs sell planes; they don't lend them."], "explanation": "Most airliners are leased. The airline flies the plane while a lessor owns it, which is why foreign firms lost jets in Russia."}, "proReasoning": "Separate who flies a plane from who owns it. Leasing makes those two different companies most of the time.", "commonMistake": "Assuming an airline owns its fleet.", "mentalModel": "The airline flies it; often someone else owns it."}}}$ml$::jsonb, ARRAY['handwritten-v1']::text[]),
($ml$2b2112bc-81f5-5f8d-b48e-04231ae03109$ml$::uuid, $ml$aerospace$ml$, 2, 2, $ml${"id": "aerospace-d2-c2", "title": "The Tier 1 that lives on repairs", "lessonTitle": "How an airliner gets paid for", "slot": 2, "type": "connect", "brief": {"headline": "CFM sells new engines at a loss or close to breakeven. Its profit comes later, from parts and service over the 20 to 25 years each engine flies.", "kicker": "Connect day 1 and day 2: the Tier 1 that earns in the MRO layer.", "fullText": "On day 1 you met CFM as a Tier 1 supplier: it builds complete engines for Airbus and Boeing jets. On day 2 you saw how it gets paid. New engines sell at a loss or breakeven. Then each engine needs parts and service for 20 to 25 years, the maintenance, repair and overhaul layer of the map.\n\nAirlines, engine makers and independent shops all compete for that work. For an engine maker, the sale opens the door. The repairs pay the bills.", "sources": [{"url": "https://www.janushenderson.com/hub/article/anatomy-of-a-good-company-safran", "label": "Janus Henderson on Safran"}, {"url": "https://www.cfmaeroengines.com/about", "label": "CFM International"}, {"url": "https://blog.brennaninc.com/what-are-the-three-tiers-in-the-aerospace-supply-chain", "label": "Brennan, aerospace supply chain tiers"}]}, "evidence": {"kind": "sortSignal", "prompt": "Is each payment part of the engine sale, or the aftermarket?", "buckets": ["Engine sale", "Aftermarket"], "items": [{"text": "Two new engines on a newly delivered jet", "bucket": 0}, {"text": "A spare engine bought with a new fleet", "bucket": 0}, {"text": "Replacement turbine blades years later", "bucket": 1}, {"text": "An overhaul at a shop visit", "bucket": 1}, {"text": "A service deal paid per flight hour", "bucket": 1}], "explanation": "The sale happens once, often near cost. Parts, overhauls and service deals keep paying for decades."}, "numbers": {"kind": "numberSense", "prompt": "At the top of the range, how many years of parts and service can follow one engine sale?", "min": 0, "max": 40, "value": 25, "unit": "years", "explanation": "Up to 25 years. That is why an engine maker can afford to sell the engine near cost."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You're interviewing for CFM's services team. The interviewer asks why the team matters if engines sell at breakeven.", "prompt": "What do you say?", "options": ["Service matters less than new engine orders", "Service is where the engine earns its profit", "Service is a cost to keep as low as possible"], "correctIndex": 1, "consequences": ["New orders matter, but most profit comes after delivery.", "The sale opens 20 to 25 years of parts and service.", "Service is a profit center, not just a cost."], "explanation": "Engine makers sell near cost and earn on parts and service. The services team is where the profit lives."}, "proReasoning": "In an interview, tie the team to the money. Saying the aftermarket pays for the engine program shows you understand the model.", "commonMistake": "Treating service as a support function rather than the profit engine.", "mentalModel": "In engines, the sale opens the door and service pays."}, "invest": {"call": {"kind": "theCall", "situation": "Two engine makers each sold 1,000 engines this year. One has a large fleet of older engines flying; the other is new to the market.", "prompt": "Which has more profit coming in now?", "options": ["The new one, with the fresh sales", "Both the same, since sales match", "The one with the big older fleet"], "correctIndex": 2, "consequences": ["Fresh engine sales are near cost, so they add little profit yet.", "Equal sales can hide very different service income.", "Older engines need parts and overhauls, which is where profit sits."], "explanation": "Profit follows the engines already flying, not this year's sales. A large flying fleet means years of service income."}, "proReasoning": "Investors look at the installed base: how many engines are flying and how old they are. That predicts service income better than new orders.", "commonMistake": "Ranking engine makers by how many engines they sold this year.", "mentalModel": "Count the fleet in the air, not the sales on paper."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your startup makes a coating that helps engine parts last longer between overhauls. You pitch CFM.", "prompt": "What reaction should you prepare for?", "options": ["Caution: it may cut its own service income", "An instant yes, since airlines would love it", "No interest, since engines are sold at cost"], "correctIndex": 0, "consequences": ["Longer life helps airlines but can shrink paid overhaul work.", "Airlines may love it; the engine maker weighs its own income.", "Engines sell near cost, which is why service income matters so much."], "explanation": "If an engine maker is paid per overhaul, fewer overhauls mean less income. Under flight-hour deals, longer life can help it instead, so learn how it is paid."}, "proReasoning": "Founders check whose income their product cuts. A buyer will hesitate over something that shrinks its own profit, even if its customers love it.", "commonMistake": "Assuming every company welcomes a product that makes its parts last longer.", "mentalModel": "Check whose income your product shrinks."}, "curiosity": {"call": {"kind": "theCall", "situation": "You read that an engine maker sells many engines at a loss and still makes big profits.", "prompt": "How can both be true?", "options": ["Airlines pay a bonus when engines arrive", "Profit comes from decades of parts and service", "The OEM pays back its losses on engines"], "correctIndex": 1, "consequences": ["There is no delivery bonus; the money comes later, from service.", "Each engine opens 20 to 25 years of aftermarket income.", "OEMs don't refund engine makers for losses."], "explanation": "The engine is sold near cost, then pays for 20 to 25 years through parts and service."}, "proReasoning": "When a sale looks unprofitable, look at what it opens up afterward. Many businesses price the first sale low to win years of follow-on income.", "commonMistake": "Judging a business by its first sale alone.", "mentalModel": "Look past the sale to what follows it."}}}$ml$::jsonb, ARRAY['handwritten-v1']::text[]),
($ml$da2fa556-0ffd-584c-a9ab-e02aa9b8849b$ml$::uuid, $ml$aerospace$ml$, 2, 3, $ml${"id": "aerospace-d2-c3", "title": "Cash before the plane", "lessonTitle": "How an airliner gets paid for", "slot": 3, "type": "decide", "brief": {"headline": "Before a jet is delivered, its buyer can pay up to 30% of the price in installments. The balance arrives only on handover day.", "kicker": "Decide how the money should move, and who should carry it.", "fullText": "Airlines and lessors pay for new jets in steps. Pre-delivery payments, made while the plane is being built, can reach 30% of the price. The balance is paid when the plane is delivered.\n\nMany airlines avoid most of that by not owning their planes at all. At the end of 2023, 58% of the world's commercial fleet was leased. A lessor can place the order, carry the payments and rent the plane out once it arrives.", "sources": [{"url": "https://bclplaw.com/en-US/insights/pdp-financing-in-aviation.html", "label": "BCLP, PDP financing in aviation"}, {"url": "https://www.iata.org/en/iata-repository/publications/economic-reports/more-aircraft-are-leased-than-owned-by-airlines-globally", "label": "IATA, more aircraft are leased than owned"}]}, "evidence": {"kind": "spotFake", "prompt": "One of these is false. Tap it.", "statements": ["Pre-delivery payments are made while the jet is built.", "Airlines must own every jet they fly.", "The balance is paid when the jet is delivered."], "fakeIndex": 1, "explanation": "58% of the world's fleet was leased at the end of 2023. Plenty of airlines fly jets they don't own."}, "numbers": {"kind": "numberSense", "prompt": "A $60 million jet, with pre-delivery payments at 30%. How much is paid before delivery, in millions of dollars?", "min": 0, "max": 60, "value": 18, "unit": "M", "explanation": "30% of $60 million is $18 million. The other $42 million arrives at handover."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You're a junior analyst at a lessor. A young airline wants 10 new jets but has little cash.", "prompt": "What can your firm offer?", "options": ["Lend it the full price of all ten jets", "Tell it to wait until it has the cash", "Buy the jets and lease them to the airline"], "correctIndex": 2, "consequences": ["That's a bank's job; lessors own the planes they rent out.", "Waiting costs the airline years in the queue for new jets.", "The lessor carries the payments; the airline pays rent from delivery."], "explanation": "Lessors buy planes and rent them out, so the airline needs far less cash up front."}, "proReasoning": "In leasing, the pitch is cash: the lessor carries the pre-delivery payments and the asset, and the airline pays rent once the plane flies.", "commonMistake": "Confusing a lessor with a lender.", "mentalModel": "Lessors trade ownership for rent."}, "invest": {"call": {"kind": "theCall", "situation": "An airline you follow has 30 jets on order and is making pre-delivery payments on all of them.", "prompt": "What should you check first?", "options": ["Its cash for payments until delivery", "Whether the jets come in its own colors", "Whether passengers like the new seats"], "correctIndex": 0, "consequences": ["Up to 30% per jet goes out before any jet earns money.", "Paint is a detail; cash is the risk.", "Seats matter later; the cash goes out first."], "explanation": "Pre-delivery payments drain cash before the planes fly. A big order book can strain a weak airline."}, "proReasoning": "Investors look at the cash going out before deliveries. An order book is a promise to pay, not just a sign of growth.", "commonMistake": "Reading a big order book as pure strength.", "mentalModel": "Orders are also obligations."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your startup plans to launch a small airline with 5 jets. Cash is tight.", "prompt": "How do you get the planes?", "options": ["Buy them outright with cash", "Lease them from a lessor", "Order new jets and pay as they're built"], "correctIndex": 1, "consequences": ["Buying outright takes cash you don't have.", "Leasing keeps cash free for running the airline.", "Pre-delivery payments would tie up cash for years."], "explanation": "Leasing is how most young airlines start: less cash up front and more freedom to grow or shrink."}, "proReasoning": "Founders in capital-heavy industries rent the expensive asset first. Leasing turns a huge upfront cost into rent paid over time.", "commonMistake": "Tying up scarce cash in assets you could rent.", "mentalModel": "Rent the asset, keep the cash."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks how an airline can order 100 planes without billions in the bank.", "prompt": "What makes it possible?", "options": ["Airlines pay nothing until the planes retire", "The OEM gives the planes away", "Payments come in steps, and lessors help"], "correctIndex": 2, "consequences": ["The balance is due at delivery, not decades later.", "OEMs sell planes; they don't give them away.", "Installments during the build, the balance at delivery, often via lessors."], "explanation": "Pre-delivery payments, the balance at delivery and leasing spread the cost over years."}, "proReasoning": "Big purchases are often paid for in stages. Look at when each payment is due, and who really owns the asset.", "commonMistake": "Picturing the whole price paid at once.", "mentalModel": "Big buys are paid in steps."}}}$ml$::jsonb, ARRAY['handwritten-v1']::text[]),
($ml$1c9a8f2d-69d5-5eb1-8097-92670f93f03a$ml$::uuid, $ml$aerospace$ml$, 3, 1, $ml${"id": "aerospace-d3-c1", "title": "One engine for the A350", "lessonTitle": "When a supplier can't be replaced", "slot": 1, "type": "apply", "brief": {"headline": "Every Airbus A350 flies on one engine family: the Rolls-Royce Trent XWB. In November 2023, Emirates said it would not order the A350-1000 until that engine lasted longer.", "kicker": "Apply the lesson: what can a buyer do against a sole source?", "fullText": "The Trent XWB is the only engine offered on the A350. An airline that wants the plane must take the Rolls-Royce engine; there is no second maker to play against it.\n\nIn November 2023, Emirates president Tim Clark said the larger A350-1000 could suit the airline, but that it would not order the plane until Rolls-Royce improved the Trent XWB-97's durability. He wanted the engine to stay on wing for 2,000 to 2,500 cycles at an acceptable cost, and warned that in Emirates' hot, dusty conditions it would reach well under a quarter of that.\n\nWith only one engine on offer, the buyer's lever was to hold back the order for the whole plane.", "sources": [{"url": "https://planefyi.com/engines/rr-trent-xwb/", "label": "PlaneFYI, Rolls-Royce Trent XWB"}, {"url": "https://flightglobal.com/airlines/emirates-will-only-assess-a350-1000-once-engines-meet-durability-demands-clark/155834.article", "label": "FlightGlobal, Emirates on the A350-1000 engine, Nov 2023"}]}, "evidence": {"kind": "faceOff", "prompt": "Who has more room to push for a better engine deal?", "left": {"name": "An A350 buyer", "note": "The Trent XWB is the only engine"}, "right": {"name": "An A320neo buyer", "note": "Can pick the LEAP-1A or the PW1100G"}, "correctIndex": 1, "explanation": "With two engine makers, the A320neo buyer can play them against each other. The A350 buyer can only walk away from the plane."}, "numbers": {"kind": "numberSense", "prompt": "Emirates wanted at least 2,000 cycles on wing, and Clark warned of well under a quarter. What is a quarter of 2,000?", "min": 0, "max": 2500, "value": 500, "unit": "cycles", "explanation": "500 cycles. Below that, the engine would need a shop visit more than four times as often as Emirates wanted."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You join Airbus's A350 sales team. An airline in a hot, dusty region worries about engine durability.", "prompt": "What can you honestly offer?", "options": ["A promise that dust won't hurt the engine", "Durability fixes and terms backed by Rolls-Royce", "A cheaper second engine option on the A350"], "correctIndex": 1, "consequences": ["Dust does wear engines; promising otherwise costs you trust.", "Honest and useful: the fix has to come from the one engine maker.", "There is no second engine on the A350 to offer."], "explanation": "With a sole-source engine, Airbus can't swap makers. It can push Rolls-Royce for fixes and better terms."}, "proReasoning": "In sales, know what you can't change. With one engine maker, your value is coordinating fixes and terms, not offering choices you don't have.", "commonMistake": "Promising options the product doesn't have.", "mentalModel": "Sell what is real; fix what you can."}, "invest": {"call": {"kind": "theCall", "situation": "You own Rolls-Royce shares. A big airline says it won't order the A350-1000 until the engine lasts longer.", "prompt": "How should you read this?", "options": ["No risk: Rolls-Royce is the only A350 engine", "Good news: more repairs mean more income", "A real risk to future orders and service income"], "correctIndex": 2, "consequences": ["Being the only engine doesn't force anyone to buy the plane.", "Under flight-hour service deals, extra repairs cost the engine maker.", "Sole source protects price, but buyers can still skip the plane."], "explanation": "Sole source gives pricing power, not guaranteed orders. A buyer can walk away from the whole plane."}, "proReasoning": "Investors separate pricing power from demand. A sole supplier can still lose when customers delay the plane it powers.", "commonMistake": "Treating sole source as a guarantee of sales.", "mentalModel": "Sole source sets the price, not the demand."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your startup has a sand filter idea that could extend engine life at dusty airports. Emirates loves it.", "prompt": "Who do you most need on your side for A350 engines?", "options": ["Rolls-Royce, the only A350 engine maker", "Emirates, since it raised the problem", "The airports with the most sand"], "correctIndex": 0, "consequences": ["With one engine maker, its support decides how far you go.", "Emirates can champion it, but it doesn't control the engine design.", "Airports suffer the dust, but they don't buy engine parts."], "explanation": "On the A350 there is one engine maker. Its support, and later a regulator's approval, decide whether your part flies."}, "proReasoning": "When a market has a sole source, that company is the gatekeeper. Founders win it over or design around it.", "commonMistake": "Thinking an enthusiastic airline is enough to change a sole-source engine.", "mentalModel": "In a sole-source market, win the gatekeeper."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks why Emirates, a huge customer, couldn't just pick another engine for the A350.", "prompt": "What's the answer?", "options": ["Emirates simply prefers Rolls-Royce", "There is no other engine for the A350", "Rolls-Royce refused to sell to Emirates"], "correctIndex": 1, "consequences": ["Preference had nothing to do with it: there's only one.", "The Trent XWB is the sole A350 engine, so a buyer can only wait or walk.", "Rolls-Royce was happy to sell; the issue was durability."], "explanation": "The A350 has one engine family. Even the biggest buyer can't switch makers; it can only delay the order."}, "proReasoning": "When a product has only one supplier, even big customers lose bargaining power. Their main move is to delay or skip the purchase.", "commonMistake": "Assuming big customers can always get what they want.", "mentalModel": "No second option, less bargaining power."}}}$ml$::jsonb, ARRAY['handwritten-v1']::text[]),
($ml$fc5252a0-515b-5ec0-9948-a047de0fd476$ml$::uuid, $ml$aerospace$ml$, 3, 2, $ml${"id": "aerospace-d3-c2", "title": "Two engines, one fight", "lessonTitle": "When a supplier can't be replaced", "slot": 2, "type": "connect", "brief": {"headline": "An A320neo buyer can choose a CFM LEAP-1A or a Pratt & Whitney PW1100G. A 737 MAX buyer gets the LEAP-1B, with no alternative.", "kicker": "Connect day 2 and day 3: why makers fight so hard for the engine sale.", "fullText": "On day 2 you saw that engines are sold near cost, and that the profit comes from 20 to 25 years of parts and service. On day 3 you saw who has a second option. A320neo buyers choose between two qualified engines, the LEAP-1A and the PW1100G, so both makers compete for each order. On the 737 MAX, the LEAP-1B is the only engine.\n\nPut the two ideas together. Winning the sale matters because it locks in decades of service income. Where there is a rival, the buyer can push the price of that first sale down.", "sources": [{"url": "https://planefyi.com/guides/aircraft-comparison/a320neo-vs-737max/", "label": "PlaneFYI, A320neo vs 737 MAX"}, {"url": "https://www.janushenderson.com/hub/article/anatomy-of-a-good-company-safran", "label": "Janus Henderson on Safran"}]}, "evidence": {"kind": "buildChain", "prompt": "Put the logic in order, from the engine choice to the profit.", "steps": ["The A320neo offers two engine makers", "Both makers compete for the airline's order", "The winner sells its engines near cost", "It earns on parts and service for decades"], "explanation": "Competition pushes the sale price down. The aftermarket is why makers still fight for every order."}, "numbers": {"kind": "numberSense", "prompt": "An airline orders 50 A320neos. How many new engines are at stake, not counting spares?", "min": 0, "max": 300, "value": 100, "explanation": "Two per jet: 100 engines, each with 20 to 25 years of service income behind it."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You're interviewing at Pratt & Whitney. They ask why one A320neo engine campaign matters so much.", "prompt": "What's the strongest answer?", "options": ["Each engine sale is very profitable on its own", "Losing means the airline flies without engines", "Each win locks in decades of service income"], "correctIndex": 2, "consequences": ["New engines often sell near cost, and the profit comes later.", "The airline would simply pick the CFM engine instead.", "The sale is near cost; the service lasts decades."], "explanation": "On the A320neo, losing an order hands decades of service income to the rival engine maker."}, "proReasoning": "Tie the campaign to lifetime value. Interviewers want to hear that one order is really 20 to 25 years of income.", "commonMistake": "Talking about the engine sale price as if it were the prize.", "mentalModel": "One order, decades of income."}, "invest": {"call": {"kind": "theCall", "situation": "Compare two engine deals: one on the A320neo, with a rival bidding; one on the 737 MAX, with no rival.", "prompt": "Where should the engine price hold up better?", "options": ["On the 737 MAX, with no rival", "On the A320neo, with a rival", "Both the same, since engines sell near cost"], "correctIndex": 0, "consequences": ["No rival on the MAX means less pressure to discount.", "A rival on every A320neo deal pushes prices down.", "Near cost is an average; competition decides how low it goes."], "explanation": "Without a competitor, the seller can hold its price. On the A320neo, two makers fight over every order."}, "proReasoning": "Investors look for where a company faces a rival at the point of sale. Pricing holds up where the buyer has no alternative.", "commonMistake": "Assuming the same product earns the same margin everywhere.", "mentalModel": "Price follows the buyer's alternatives."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your startup builds a tool that compares engine offers line by line for airlines.", "prompt": "Which customers need it most?", "options": ["A350 buyers, with one engine family", "A320neo buyers choosing between two engines", "737 MAX buyers, with one engine option"], "correctIndex": 1, "consequences": ["The A350 has only the Trent XWB, so there is no choice to weigh.", "Two competing offers is exactly where comparison pays.", "With one engine on offer, there's nothing to compare."], "explanation": "Comparison only helps when there is a real choice. The A320neo gives buyers two engine makers."}, "proReasoning": "Founders look for decisions with real alternatives. A tool that compares offers needs at least two offers.", "commonMistake": "Building for the biggest market rather than the one with a real choice.", "mentalModel": "No choice, no comparison market."}, "curiosity": {"call": {"kind": "theCall", "situation": "At the gate, a friend notices two A320neos with different-looking engines.", "prompt": "Why could that be?", "options": ["One of them is a much older model", "Airbus builds two kinds of its own engine", "Airlines can pick between two engine makers"], "correctIndex": 2, "consequences": ["Both can be new A320neos with different engine makers.", "Airbus doesn't build engines; CFM and Pratt & Whitney do.", "The A320neo offers the LEAP-1A and the PW1100G."], "explanation": "The A320neo has two engine options from two makers. Different airlines, different choices."}, "proReasoning": "Engines are a separate choice from the plane. On some models, airlines pick the maker, and that choice lasts for decades.", "commonMistake": "Thinking the plane maker builds the engines.", "mentalModel": "Same plane, choice of engine."}}}$ml$::jsonb, ARRAY['handwritten-v1']::text[]),
($ml$7242b527-4114-56f5-8ba6-b5efd9fd9a31$ml$::uuid, $ml$aerospace$ml$, 3, 3, $ml${"id": "aerospace-d3-c3", "title": "Rescue or replace?", "lessonTitle": "When a supplier can't be replaced", "slot": 3, "type": "decide", "brief": {"headline": "On December 8, 2025, Boeing and Airbus each completed deals to take over parts of Spirit AeroSystems. Two rivals paid to own a supplier neither could replace.", "kicker": "Decide what you would do when a sole source starts to fail.", "fullText": "Spirit AeroSystems built 737 fuselages and major parts of the 767, 777 and 787 for Boeing, plus A350 fuselage sections and A220 wings for Airbus. In 2024 it lost $2.14 billion on $6.3 billion of revenue. A Spirit-built fuselage had also reached Boeing with improperly installed rivets, the start of the chain that led to the Alaska Airlines door plug blowout.\n\nReplacing Spirit would have meant new tooling, tests and approvals. On December 8, 2025, Boeing completed its purchase of Spirit's Boeing work, and Airbus closed its purchase of the sites building Airbus parts.", "sources": [{"url": "https://www.spiritaero.com/company/overview/history/", "label": "Spirit AeroSystems history"}, {"url": "https://www.manufacturingdive.com/news/spirit-aerosystems-q4-2024-airbus-boeing-supplier-merger-acquisition/741460/", "label": "Manufacturing Dive, Spirit AeroSystems 2024 results"}, {"url": "https://www.airlinegeeks.com/2025/07/10/ntsb-releases-final-report-on-alaska-door-plug-blowout/", "label": "AirlineGeeks on the NTSB report"}, {"url": "https://boeing.mediaroom.com/2025-12-08-Boeing-Completes-Acquisition-of-Spirit-Aerosystems", "label": "Boeing, Dec 2025"}, {"url": "https://www.airbus.com/en/newsroom/press-releases/2025-12-airbus-completes-acquisition-of-spirit-aerosystems-sites", "label": "Airbus, Dec 2025"}]}, "evidence": {"kind": "sortSignal", "prompt": "Does each fact make a supplier harder or easier to replace?", "buckets": ["Harder to replace", "Easier to replace"], "items": [{"text": "Only one company has the tooling for the part", "bucket": 0}, {"text": "A new supplier would need new tests and approvals", "bucket": 0}, {"text": "Years of approvals are tied to its sites", "bucket": 0}, {"text": "A rival plant is already qualified on the part", "bucket": 1}, {"text": "Spare tooling sits ready at another site", "bucket": 1}], "explanation": "Tooling, tests and approvals tie a part to one supplier. A qualified second source is what breaks that hold."}, "numbers": {"kind": "numberSense", "prompt": "Spirit lost $2.14 billion in 2024 on $6.3 billion of revenue. Roughly how many cents did it lose per dollar of sales?", "min": 0, "max": 100, "value": 34, "unit": "¢", "explanation": "About 34 cents on every dollar. A supplier losing that much cannot keep going alone, yet its customers could not do without it."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You're a supply chain analyst at an OEM. Your only supplier of a key structure is losing money.", "prompt": "What do you recommend first?", "options": ["Map what it would take to qualify a backup", "Cancel the contract and buy elsewhere next month", "Ignore it while deliveries still arrive"], "correctIndex": 0, "consequences": ["You size the real alternative before anyone panics or pays.", "No one else can build it next month; tooling and approvals take time.", "Waiting until deliveries stop leaves you no time at all."], "explanation": "Before rescuing or replacing, know what a second source would cost and how long it would take."}, "proReasoning": "Supply chain pros measure the exit before choosing a path. Knowing the cost and time of a second source gives you options at the table.", "commonMistake": "Threatening to walk away from a supplier you can't actually replace.", "mentalModel": "Know your exit before you negotiate."}, "invest": {"call": {"kind": "theCall", "situation": "You own shares in an OEM that just bought its struggling sole-source supplier.", "prompt": "What should you watch next?", "options": ["Whether rivals start buying from the plant", "Whether the plant's costs and quality improve", "Whether the supplier's old prices go up"], "correctIndex": 1, "consequences": ["The plant now builds mainly for its new owner.", "The OEM now owns the losses, so the fix must show in its results.", "There's no outside price anymore; the costs are the OEM's own."], "explanation": "After a buyback, the supplier's losses and quality problems sit on the OEM's books. The turnaround is the story to track."}, "proReasoning": "Investors treat a rescue as a bet on a turnaround. The question becomes how fast the new owner can cut costs and fix quality.", "commonMistake": "Celebrating control without pricing in the losses that came with it.", "mentalModel": "A rescue is a turnaround bet."}, "build_startup": {"call": {"kind": "theCall", "situation": "You run a small machine shop. An OEM worries that its only supplier of a structural part could fail.", "prompt": "What's your best move?", "options": ["Undercut the supplier's price next week", "Wait until the supplier actually fails", "Offer to become a qualified second source"], "correctIndex": 2, "consequences": ["Price doesn't matter until you're qualified to build the part.", "When it fails, the OEM needs parts now, and you're not approved.", "Qualifying takes time, but it's exactly what the OEM lacks."], "explanation": "OEMs value a qualified backup. Qualification is slow, which is why starting early wins."}, "proReasoning": "Founders find openings where a customer is exposed. A nervous OEM with one supplier is a buyer for a second qualified source.", "commonMistake": "Competing on price for a part you aren't yet approved to make.", "mentalModel": "Be the backup before it's needed."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks why Airbus helped take over a supplier best known for Boeing fuselages.", "prompt": "Why would a rival step in?", "options": ["Airbus also relied on Spirit for key parts", "Airbus wanted to own Boeing's factories", "A regulator ordered Airbus to buy it"], "correctIndex": 0, "consequences": ["Spirit built A350 fuselage sections and A220 wings for Airbus.", "Airbus took only the sites building its own parts.", "Airbus bought because it needed those parts, not on orders."], "explanation": "Airbus bought the Spirit sites making its own parts. It couldn't replace them either."}, "proReasoning": "When rivals act alike, look for a shared dependency. Here both needed the same hard-to-replace supplier.", "commonMistake": "Reading every move as competition; some are protection.", "mentalModel": "A shared dependency can make rivals act alike."}}}$ml$::jsonb, ARRAY['handwritten-v1']::text[]),
($ml$6d92c0ad-5f1c-52b2-9359-56802e9a8bf6$ml$::uuid, $ml$aerospace$ml$, 4, 1, $ml${"id": "aerospace-d4-c1", "title": "Boeing's year in three numbers", "lessonTitle": "Three numbers that tell the story", "slot": 1, "type": "apply", "brief": {"headline": "Boeing delivered 600 jets in 2025, up from 348 the year before. It booked 1,075 new orders and ended the year with 6,130 planes in its backlog.", "kicker": "Apply the three numbers to Boeing's year.", "fullText": "Early figures for 2025 showed Boeing delivering 600 commercial jets across its four major programs, about 42% more than the 348 it delivered in 2024. It booked 1,075 new orders, and its commercial backlog stood at 6,130 aircraft. These were preliminary numbers reported in January 2026, before Boeing's official results.\n\nPut them through the day 4 lens: backlog for demand, deliveries for cash, and book-to-bill for the direction the backlog is heading.", "sources": [{"url": "https://americanmachinist.com/55343304", "label": "American Machinist, Boeing 2025 deliveries and orders"}]}, "evidence": {"kind": "multipleChoice", "prompt": "Boeing booked 1,075 orders and delivered 600 jets in 2025. What happened to its backlog?", "options": ["It grew, since book-to-bill was above 1", "It shrank, since deliveries beat orders", "It stayed flat, since both numbers rose"], "correctIndex": 0, "explanation": "1,075 in, 600 out. A book-to-bill near 1.8 means the backlog grew."}, "numbers": {"kind": "numberSense", "prompt": "At 600 deliveries a year, about how many years would Boeing's 6,130-plane backlog last?", "min": 0, "max": 30, "value": 10, "unit": "years", "explanation": "6,130 divided by 600 is about 10 years, close to Airbus's 11."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You're interviewing at Boeing in early 2026. They ask what you know about the company's year.", "prompt": "Which answer lands best?", "options": ["It's a huge company with many plane models", "Its huge backlog means it has no problems", "600 deliveries, up from 348, backlog growing"], "correctIndex": 2, "consequences": ["True, but it says nothing you couldn't say about any OEM.", "A backlog is demand, and the factory still has to build it.", "One real number and a direction is exactly what they want."], "explanation": "Concrete numbers show you follow the business. Deliveries tell them you know where the cash comes from."}, "proReasoning": "Bring one or two real numbers and what they mean. Deliveries up sharply with a growing backlog says recovery, with work still ahead.", "commonMistake": "Using a big backlog as proof that all is well.", "mentalModel": "One number, one meaning."}, "invest": {"call": {"kind": "theCall", "situation": "Boeing's backlog grew in 2025. A friend says that makes the stock a sure win.", "prompt": "What else must you check?", "options": ["Whether the delivery rate keeps rising", "Whether the backlog is a nice round number", "Nothing, since a growing backlog is enough"], "correctIndex": 0, "consequences": ["Cash comes at delivery, so the rate turns backlog into revenue.", "Round numbers don't pay, but deliveries do.", "A backlog that can't be built is only a promise."], "explanation": "The backlog is signed demand. Revenue arrives only as fast as the factory delivers."}, "proReasoning": "Investors pair the backlog with the build rate. A record backlog with a stuck rate means cash arrives slowly.", "commonMistake": "Treating orders as revenue.", "mentalModel": "Backlog is demand; deliveries are cash."}, "build_startup": {"call": {"kind": "theCall", "situation": "You sell a part fitted to every Boeing jet. Boeing plans to build more planes each month in 2026.", "prompt": "How should you plan your own output?", "options": ["Keep output flat until the backlog shrinks", "Follow Boeing's delivery rate, not its orders", "Follow Boeing's 1,075 new orders"], "correctIndex": 1, "consequences": ["The backlog grew, so flat output could leave Boeing short.", "You build to what Boeing actually assembles each month.", "Orders arrive years before Boeing builds those planes."], "explanation": "Suppliers sell at the pace Boeing builds. Orders tell you how long demand lasts, not how fast it comes."}, "proReasoning": "Founders in supply chains plan to the OEM's monthly rate. The backlog tells them how long that rate can last.", "commonMistake": "Scaling to the order headline instead of the build rate.", "mentalModel": "Build to the rate; the backlog sets the horizon."}, "curiosity": {"call": {"kind": "theCall", "situation": "News says Boeing has thousands of planes on order, yet airlines complain they can't get jets.", "prompt": "How can both be true?", "options": ["Airlines cancel every order they place", "The orders are for planes no one wants", "Orders pile up faster than planes get built"], "correctIndex": 2, "consequences": ["Some orders get cancelled, but most stand.", "Airlines want them; they just have to wait their turn.", "With about 10 years of work in the backlog, waits are long."], "explanation": "A backlog of about 10 years means airlines wait. More demand doesn't mean more planes this year."}, "proReasoning": "When demand outruns capacity, the backlog grows and waits get longer. The factory, not the order book, sets the pace.", "commonMistake": "Thinking orders and deliveries move together.", "mentalModel": "Capacity sets the pace, not demand."}}}$ml$::jsonb, ARRAY['handwritten-v1']::text[]),
($ml$6bb746f0-7245-5757-b6ed-1097c2d8f251$ml$::uuid, $ml$aerospace$ml$, 4, 2, $ml${"id": "aerospace-d4-c2", "title": "Where the cash lands", "lessonTitle": "Three numbers that tell the story", "slot": 2, "type": "connect", "brief": {"headline": "Airbus delivered 793 jets in 2025. Buyers can pay up to 30% of a jet's price before delivery, and the balance arrives on handover day.", "kicker": "Connect day 2 and day 4: why deliveries, not orders, bring the cash.", "fullText": "On day 2 you saw how buyers pay: pre-delivery payments during the build, which can reach 30% of the price, and the balance at delivery. On day 4 you saw Airbus deliver 793 aircraft in 2025, against a backlog of 8,754.\n\nPut them together. An order brings little cash at first. Most of the price arrives the day the plane is handed over. That is why plane makers, and the people who follow them, watch deliveries so closely.", "sources": [{"url": "https://bclplaw.com/en-US/insights/pdp-financing-in-aviation.html", "label": "BCLP, PDP financing in aviation"}, {"url": "https://www.airbus.com/en/newsroom/press-releases/2026-01-airbus-reports-793-commercial-aircraft-deliveries-in-2025", "label": "Airbus, 2025 deliveries"}]}, "evidence": {"kind": "spotFake", "prompt": "One of these is false. Tap it.", "statements": ["Pre-delivery payments can reach 30% of the price.", "An order alone brings in most of a jet's price.", "The balance is paid when the plane is delivered."], "fakeIndex": 1, "explanation": "Most of the price comes at delivery. An order starts the payments; it doesn't complete them."}, "numbers": {"kind": "numberSense", "prompt": "If pre-delivery payments reach 30%, what share of a jet's price is still due at delivery?", "min": 0, "max": 100, "value": 70, "unit": "%", "explanation": "At least 70% arrives on handover day. Deliveries are where the cash lands."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You work in Airbus finance. A big delivery slips from late December to January.", "prompt": "What's the main effect on this year's numbers?", "options": ["The balance moves into next year's cash", "The order is cancelled", "Nothing, since the order was already signed"], "correctIndex": 0, "consequences": ["Most of the price arrives at handover, so the cash moves with it.", "A slip delays the plane, and the order still stands.", "Signing isn't payment, since most money comes at delivery."], "explanation": "The balance is paid on delivery. A slip of a few weeks can move a big payment into the next year."}, "proReasoning": "Finance teams track delivery timing closely because cash follows the handover. A December slip can change the whole year's result.", "commonMistake": "Assuming a signed order means the money is in.", "mentalModel": "Cash follows the handover."}, "invest": {"call": {"kind": "theCall", "situation": "An OEM reports record orders but fewer deliveries than planned.", "prompt": "What do you expect for this year's cash?", "options": ["Unchanged, since the two cancel out", "Weaker, since cash comes mostly at delivery", "Stronger, thanks to the record orders"], "correctIndex": 1, "consequences": ["They don't cancel out, because deliveries carry the cash.", "Fewer handovers means less of the balance arrives.", "Orders bring only early payments, not the bulk of the price."], "explanation": "Deliveries bring the cash. Record orders help later years, not this one."}, "proReasoning": "Read orders as future revenue and deliveries as today's cash. When they diverge, the cash follows deliveries.", "commonMistake": "Letting order headlines stand in for cash.", "mentalModel": "Orders are tomorrow; deliveries are today."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your startup builds cabin parts. An airline wants to pay you the way it pays for planes: a little now, the rest on delivery.", "prompt": "What's the risk to your cash?", "options": ["You get paid far too early", "There's no risk once the order is signed", "You fund most of the build until delivery"], "correctIndex": 2, "consequences": ["Early payments help you; the problem is waiting for the rest.", "A signed order doesn't pay your bills until delivery.", "Like an OEM, you carry the build cost until the balance arrives."], "explanation": "When most money comes at delivery, the builder funds the work until then. Small companies feel that hardest."}, "proReasoning": "Founders plan cash around when the customer pays, not when it signs. Payment terms can matter as much as price.", "commonMistake": "Celebrating the order without planning how to fund the build.", "mentalModel": "Plan cash around payment, not signature."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks why plane makers rush to deliver jets before the end of December.", "prompt": "What's the likely reason?", "options": ["Delivered jets bring cash into that year", "Airlines only fly new jets in winter", "Planes built in December are cheaper"], "correctIndex": 0, "consequences": ["The balance arrives at handover, so a December delivery counts this year.", "Airlines fly new jets all year round.", "The build cost doesn't depend on the month."], "explanation": "Most of the price is paid on delivery. A jet handed over in December counts in that year's cash."}, "proReasoning": "Look at when money changes hands to explain behavior. Year-end rushes happen when payment follows delivery.", "commonMistake": "Looking for an operational reason when the reason is cash timing.", "mentalModel": "Follow the money to explain the timing."}}}$ml$::jsonb, ARRAY['handwritten-v1']::text[]),
($ml$a4d5d921-39e6-5f34-b8de-dcd855db0b88$ml$::uuid, $ml$aerospace$ml$, 4, 3, $ml${"id": "aerospace-d4-c3", "title": "From 38 to 42 a month", "lessonTitle": "Three numbers that tell the story", "slot": 3, "type": "decide", "brief": {"headline": "From early 2024 to October 2025, the FAA held Boeing to 38 737 MAX a month. Then it allowed 42.", "kicker": "Decide what a higher rate means from where you sit.", "fullText": "Rate is the number of planes built per month. After the January 2024 door plug blowout, the FAA capped 737 MAX output at 38 a month. In October 2025 it allowed Boeing to go to 42.\n\nA higher rate means more deliveries, more cash and faster progress through the backlog, but only if every supplier can keep up with the new pace.", "sources": [{"url": "https://www.manufacturing.net/aerospace/news/22952957/faa-allows-boeing-to-increase-737-max-production-nearly-two-years-after-door-plug-flew-off-plane", "label": "Manufacturing.net, Oct 2025"}]}, "evidence": {"kind": "sortSignal", "prompt": "Does a rate rise from 38 to 42 a month change each of these?", "buckets": ["Changes", "Doesn't change"], "items": [{"text": "Planes delivered each month", "bucket": 0}, {"text": "Cash arriving each month", "bucket": 0}, {"text": "Parts each supplier must ship", "bucket": 0}, {"text": "The number of planes already ordered", "bucket": 1}, {"text": "The 737 MAX's approved design", "bucket": 1}], "explanation": "A higher rate speeds deliveries, cash and supplier demand. It doesn't change what is already ordered or the approved design."}, "numbers": {"kind": "numberSense", "prompt": "Going from 38 to 42 a month, how many more 737 MAX can Boeing build in a year?", "min": 0, "max": 120, "value": 48, "explanation": "Four more a month is 48 more a year, each one a delivery and a payment."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You're a supplier quality engineer at Boeing. The 737 MAX rate just went from 38 to 42 a month.", "prompt": "What's your first worry?", "options": ["Whether the backlog will run out soon", "Which suppliers can't keep up with 42", "Whether airlines still want the plane"], "correctIndex": 1, "consequences": ["About 10 years of backlog will not run out soon.", "The slowest supplier sets the real rate, and quality slips under strain.", "Demand isn't the issue, since the backlog covers years."], "explanation": "A rate rise strains every supplier. The weakest one, not the plan, decides the real pace."}, "proReasoning": "Experienced engineers check the weakest link before a rate rise. A missing part or a rushed job can stop the line or bring back a cap.", "commonMistake": "Assuming the whole chain moves up the moment the OEM does.", "mentalModel": "The slowest supplier sets the real rate."}, "invest": {"call": {"kind": "theCall", "situation": "Boeing may now build 42 MAX a month instead of 38. You are deciding whether to raise your forecast.", "prompt": "What should you base it on?", "options": ["The FAA's approval of 42 on its own", "The size of the order backlog alone", "Signs that 42 a month is really reached"], "correctIndex": 2, "consequences": ["Approval allows 42; it doesn't build them.", "The backlog covers demand, and the rate decides the pace.", "Approval is permission, and the rate must show up in deliveries."], "explanation": "Permission is not production. Forecast from deliveries that show the new rate is real."}, "proReasoning": "Investors wait for evidence in monthly deliveries before banking a rate increase. Plans in aerospace slip often.", "commonMistake": "Treating an allowed rate as an achieved one.", "mentalModel": "Permission isn't production."}, "build_startup": {"call": {"kind": "theCall", "situation": "Boeing goes from 38 to 42 a month. Your startup makes a small part used on every 737 MAX.", "prompt": "What do you do with the news?", "options": ["Plan roughly 10% more output", "Double output to be on the safe side", "Wait until Boeing calls you about it"], "correctIndex": 0, "consequences": ["42 is about 10% above 38, so plan for that and secure your own inputs.", "Doubling ties up cash in parts Boeing won't take.", "By then you could be the reason the line slows."], "explanation": "38 to 42 is roughly a 10% rise. Plan for it, and make sure your own inputs can keep up."}, "proReasoning": "Founders turn a rate change into a percentage and plan their whole chain to it. Overbuilding burns cash; underbuilding loses the customer.", "commonMistake": "Reacting to the headline instead of the math.", "mentalModel": "Turn the rate change into a percentage."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend reads that the FAA lets Boeing build 42 planes a month and asks why a regulator decides that.", "prompt": "What's the best answer?", "options": ["It owns a stake in Boeing's factories", "It capped output after a quality failure", "It decides how many jets airlines may buy"], "correctIndex": 1, "consequences": ["The FAA regulates Boeing; it doesn't own it.", "The cap followed the 2024 door plug blowout and stayed until quality improved.", "Airlines buy as many as they like, and the FAA governs safety."], "explanation": "The FAA capped the 737 MAX at 38 after the door plug blowout and allowed 42 after reviewing Boeing's lines."}, "proReasoning": "In aerospace, the regulator can slow production when quality slips. Rate is partly a business plan and partly a permission.", "commonMistake": "Thinking the rate is purely a business decision.", "mentalModel": "In aerospace, safety can set the speed."}}}$ml$::jsonb, ARRAY['handwritten-v1']::text[]),
($ml$0ce2f6e1-2cd6-5842-a021-dd6f8c098604$ml$::uuid, $ml$aerospace$ml$, 5, 1, $ml${"id": "aerospace-d5-c1", "title": "120 Dreamliners waiting", "lessonTitle": "Why a regulator sets the pace", "slot": 1, "type": "apply", "brief": {"headline": "In mid-2022, Boeing had 120 undelivered 787 Dreamliners in inventory. When the FAA cleared deliveries to resume, it said it would inspect each plane itself first.", "kicker": "Apply the lesson: a regulator can set the pace of deliveries too.", "fullText": "Boeing had suspended 787 deliveries for much of the two years before August 2022, while it and the FAA reviewed a series of manufacturing flaws, including tiny spacing errors in some fuselage parts. By mid-2022, 120 787s sat in inventory. Boeing said the 787 problems, including a drop in production, would cost $5.5 billion, and it had to compensate buyers for the delays.\n\nIn August 2022 the FAA said Boeing had made the changes needed for the 787 to meet all certification standards. Deliveries could resume, but the FAA would inspect each aircraft before an airworthiness certificate was issued.", "sources": [{"url": "https://www.cnbc.com/2022/08/08/boeing-dreamliner-deliveries-to-resume-in-the-coming-days-faa-says.html", "label": "CNBC, 787 deliveries to resume, Aug 2022"}, {"url": "https://www.faa.gov/aircraft/air_cert/production_approvals/prod_cert", "label": "FAA, production certificates"}]}, "evidence": {"kind": "buildChain", "prompt": "Put the 787 story in order.", "steps": ["Flaws show up in how fuselage parts fit", "Deliveries stop while the FAA reviews them", "Finished 787s pile up, 120 in inventory", "Boeing fixes its process and the stored jets", "The FAA inspects each plane before delivery"], "explanation": "The regulator decided when deliveries could restart, and kept checking each plane afterward."}, "numbers": {"kind": "numberSense", "prompt": "Boeing put the cost of its 787 problems at how many billion dollars?", "min": 0, "max": 20, "value": 5.5, "unit": "B", "explanation": "$5.5 billion, including the drop in production, plus payments to buyers for the delays."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You're a quality inspector at Boeing in 2022. The FAA now inspects every 787 before delivery.", "prompt": "How do you help speed things up?", "options": ["Make each plane pass the first time", "Ask the FAA to skip some checks", "Ship planes before the inspection"], "correctIndex": 0, "consequences": ["Clean planes clear faster and rebuild the FAA's trust.", "Asking to skip checks after a quality failure sets you back.", "Delivering without the certificate isn't allowed."], "explanation": "When the regulator inspects every plane, first-time quality is the only lever that speeds deliveries."}, "proReasoning": "Quality people know trust is rebuilt one clean inspection at a time. Speed follows quality, not the other way round.", "commonMistake": "Treating inspections as an obstacle to work around.", "mentalModel": "Speed follows quality."}, "invest": {"call": {"kind": "theCall", "situation": "It's August 2022. The FAA clears 787 deliveries to resume, with an inspection of every plane.", "prompt": "What does that mean for Boeing's cash?", "options": ["Cash drops, since inspections cost money", "Cash should flow as the 120 stored jets go out", "Nothing changes until new orders arrive"], "correctIndex": 1, "consequences": ["Inspections take time but release far more cash than they cost.", "Each delivered jet brings its balance, so the inventory turns into cash.", "The planes are already sold, and delivery releases the money."], "explanation": "Stored jets are cash waiting to be collected. Delivery approval turns that inventory into revenue."}, "proReasoning": "Investors see undelivered jets as stuck cash. A regulator's green light can release billions, but the pace of inspections sets the timing.", "commonMistake": "Waiting for new orders to drive cash when sold planes are waiting to go.", "mentalModel": "Undelivered jets are stuck cash."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your startup makes a tool that measures tiny gaps between fuselage parts.", "prompt": "When is the best time to pitch Boeing?", "options": ["After everyone forgets the 787 problems", "Only once the FAA stops inspecting", "While the FAA demands proof on every 787"], "correctIndex": 2, "consequences": ["When the pain fades, so does the urgency to buy.", "By then the urgency, and the budget, may be gone.", "Your tool helps prove each plane meets the standard right now."], "explanation": "Regulatory pressure creates urgent demand for tools that prove quality. Pitch while the pain is real."}, "proReasoning": "Founders time their pitch to the customer's pain. A regulator demanding proof on every plane is about the strongest buying signal there is.", "commonMistake": "Waiting for calm when the crisis is what opens the budget.", "mentalModel": "Pitch when the pain is real."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks why Boeing couldn't just deliver the 120 finished 787s waiting outside.", "prompt": "What was stopping them?", "options": ["The FAA had to clear them first", "Airlines no longer wanted the jets", "No pilots were free to fly them"], "correctIndex": 0, "consequences": ["Each plane needs an airworthiness certificate before delivery.", "Airlines wanted them, and Boeing paid them for the delays.", "Pilots weren't the issue; approval was."], "explanation": "A finished plane can't be delivered without an airworthiness certificate, and the FAA held those until quality was fixed."}, "proReasoning": "Built is not the same as approved. In aerospace, each plane needs its own paperwork before it can fly for an airline.", "commonMistake": "Thinking a finished plane is ready to deliver.", "mentalModel": "Built isn't approved."}}}$ml$::jsonb, ARRAY['handwritten-v1']::text[]),
($ml$55221299-1fa4-557e-96a6-b746d761c807$ml$::uuid, $ml$aerospace$ml$, 5, 2, $ml${"id": "aerospace-d5-c2", "title": "From a rivet to a rate cap", "lessonTitle": "Why a regulator sets the pace", "slot": 2, "type": "connect", "brief": {"headline": "The door plug that blew out in January 2024 had been removed at Renton to fix rivets on a Spirit-built fuselage. It went back without its four bolts.", "kicker": "Connect day 3 and day 5: a supplier's flaw, the OEM's responsibility.", "fullText": "On day 3 you met Spirit AeroSystems, the hard-to-replace builder of 737 fuselages. On day 5 you saw what happened next. A Spirit fuselage reached Boeing's Renton factory with improperly installed rivets. Boeing workers removed the door plug to repair them, Boeing's process for tracking removed parts was not followed, and the plug went back without its four bolts.\n\nOn January 5, 2024, it blew out of an Alaska Airlines 737 MAX 9. The NTSB found that Boeing bore ultimate responsibility, citing inadequate training and oversight, and faulted the FAA's enforcement. The FAA capped 737 MAX output at 38 a month and allowed 42 only in October 2025.", "sources": [{"url": "https://ntsb.gov/investigations/Pages/DCA24MA063.aspx", "label": "NTSB, Alaska Airlines flight 1282"}, {"url": "https://www.airlinegeeks.com/2025/07/10/ntsb-releases-final-report-on-alaska-door-plug-blowout/", "label": "AirlineGeeks on the NTSB report"}, {"url": "https://www.spiritaero.com/company/overview/history/", "label": "Spirit AeroSystems history"}, {"url": "https://www.manufacturing.net/aerospace/news/22952957/faa-allows-boeing-to-increase-737-max-production-nearly-two-years-after-door-plug-flew-off-plane", "label": "Manufacturing.net, Oct 2025"}]}, "evidence": {"kind": "faceOff", "prompt": "The NTSB named who bore ultimate responsibility. Who was it?", "left": {"name": "Spirit AeroSystems", "note": "Built the fuselage with faulty rivets"}, "right": {"name": "Boeing", "note": "Removed the plug and put it back"}, "correctIndex": 1, "explanation": "The NTSB found Boeing bore ultimate responsibility, citing inadequate training and oversight. The OEM answers for the whole plane."}, "numbers": {"kind": "numberSense", "prompt": "From early 2024 to October 2025, about how many months was the 737 MAX held at 38 a month?", "min": 0, "max": 48, "value": 21, "unit": "months", "explanation": "About 21 months. One set of missing bolts held back the whole line for most of two years."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You're a new quality lead at Boeing. A supplier's fuselage arrives with rivet defects again.", "prompt": "What's the right move?", "options": ["Send the plane on and flag it later", "Log the rework and track every part removed", "Fix it quietly to keep the line moving"], "correctIndex": 1, "consequences": ["A problem flagged later can fly in the meantime.", "The plug went back without bolts because the removal wasn't tracked.", "Quiet fixes are how parts go missing from the record."], "explanation": "The NTSB found Boeing's process for tracking removed parts wasn't followed. Documented rework is the fix."}, "proReasoning": "Quality leads know the OEM owns a supplier's defect once it reaches its line. Every removal is recorded and checked before the plane moves on.", "commonMistake": "Treating a supplier's defect as the supplier's problem once it's on your line.", "mentalModel": "On your line, it's your defect."}, "invest": {"call": {"kind": "theCall", "situation": "A key supplier ships a defect, the OEM's line mishandles the repair, and the regulator caps output.", "prompt": "Whose results take the biggest hit?", "options": ["The supplier's alone, since it made the defect", "Neither, since the cap is only temporary", "The OEM's, through capped deliveries"], "correctIndex": 2, "consequences": ["The supplier suffers too, but the OEM's capped deliveries cost more.", "Temporary here meant about 21 months.", "Capped deliveries mean less cash for the OEM for as long as the cap lasts."], "explanation": "The OEM answers for the plane. When the regulator caps output, its deliveries and cash take the hit."}, "proReasoning": "Investors trace quality failures to the deliveries they block. The cap, more than the defect, is what moved Boeing's numbers.", "commonMistake": "Thinking supplier defects only hurt the supplier.", "mentalModel": "The OEM answers for the whole plane."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your startup builds software that tracks every part removed and put back on the line.", "prompt": "Which fact makes your pitch strongest?", "options": ["Boeing's tracking of removed parts wasn't followed", "Spirit's fuselage arrived with faulty rivets", "The plug blew out climbing out of Portland"], "correctIndex": 0, "consequences": ["That's the exact gap your software closes.", "True, but your tool tracks removals, not rivet quality.", "A vivid detail, but it doesn't show the gap you fix."], "explanation": "The root cause your product fixes is untracked removals. Tie your pitch to that finding."}, "proReasoning": "Founders anchor a pitch in the investigation's finding that matches their product. A specific root cause beats a dramatic headline.", "commonMistake": "Pitching the drama instead of the gap.", "mentalModel": "Pitch the root cause you fix."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend blames the supplier: Spirit built the fuselage, so it's Spirit's fault.", "prompt": "What did the NTSB conclude?", "options": ["Alaska Airlines was mainly at fault", "Boeing bore ultimate responsibility", "Spirit bore all of the responsibility"], "correctIndex": 1, "consequences": ["The airline flew the plane as Boeing delivered it.", "Boeing removed the plug without tracking it, and the OEM answers for the plane.", "Spirit's rivets started it, but Boeing's process let it fly."], "explanation": "The NTSB found Boeing bore ultimate responsibility, citing training and oversight, and faulted the FAA's enforcement."}, "proReasoning": "Look past the first mistake to the system that let it through. Responsibility often sits with whoever was supposed to catch it.", "commonMistake": "Stopping at the first error in the chain.", "mentalModel": "Ask who was supposed to catch it."}}}$ml$::jsonb, ARRAY['handwritten-v1']::text[]),
($ml$946d9c39-0010-5e7e-986e-bb6ff1ecc1ad$ml$::uuid, $ml$aerospace$ml$, 5, 3, $ml${"id": "aerospace-d5-c3", "title": "Design approved, factory doubted", "lessonTitle": "Why a regulator sets the pace", "slot": 3, "type": "decide", "brief": {"headline": "The door plug failed because of how one plane was built, not how the 737 MAX 9 was designed. The FAA answered by capping the factory at 38 a month.", "kicker": "Decide which approval is on the line.", "fullText": "Every airliner needs two kinds of approval. A type certificate, from the FAA in the US or EASA in Europe, approves the design down to every part. A production certificate lets a factory build copies of that design, and every plane that leaves must match it.\n\nThe Alaska Airlines plane left the factory not matching its approved design: four bolts were missing, and the NTSB found that even one would have kept the plug in place. The FAA's response targeted production. It capped 737 MAX output at 38 a month and reviewed Boeing's lines before allowing 42 in October 2025.", "sources": [{"url": "https://www.faa.gov/newsroom/how-it-works-aircraft-certification", "label": "FAA, How aircraft certification works"}, {"url": "https://www.faa.gov/aircraft/air_cert/production_approvals/prod_cert", "label": "FAA, production certificates"}, {"url": "https://www.skybrary.aero/index.php/Certification_of_Aircraft,_Design_and_Production", "label": "SKYbrary, aircraft certification"}, {"url": "https://www.airlinegeeks.com/2025/07/10/ntsb-releases-final-report-on-alaska-door-plug-blowout/", "label": "AirlineGeeks on the NTSB report"}, {"url": "https://www.manufacturing.net/aerospace/news/22952957/faa-allows-boeing-to-increase-737-max-production-nearly-two-years-after-door-plug-flew-off-plane", "label": "Manufacturing.net, Oct 2025"}]}, "evidence": {"kind": "sortSignal", "prompt": "Which approval does each item test?", "buckets": ["Type certificate", "Production certificate"], "items": [{"text": "Whether the door plug's design holds in flight", "bucket": 0}, {"text": "Whether new flight software is safe as designed", "bucket": 0}, {"text": "Whether the factory installs all four bolts", "bucket": 1}, {"text": "Whether every plane matches the approved design", "bucket": 1}, {"text": "How many planes the line may build each month", "bucket": 1}], "explanation": "The type certificate covers the design. The production certificate covers building copies that match it."}, "numbers": {"kind": "numberSense", "prompt": "The NTSB found that one of the four missing bolts would have kept the plug in place. What share is one of four?", "min": 0, "max": 100, "value": 25, "unit": "%", "explanation": "One of four, 25%. The design had margin to spare; the build left none."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You can join an OEM in design certification or in production quality. You want to work where the 737 MAX cap was decided.", "prompt": "Which team was at the center of it?", "options": ["Design certification", "Neither, since it was sales", "Production quality"], "correctIndex": 2, "consequences": ["The design wasn't what failed in the door plug case.", "Sales had nothing to do with it, since the regulator acted.", "The cap targeted the factory's ability to build to the design."], "explanation": "The door plug was a build failure. The FAA's cap was aimed at production, not the design."}, "proReasoning": "Knowing which approval a problem touches tells you which team is on the hook. Interviewers like candidates who can say which.", "commonMistake": "Calling every safety problem a design problem.", "mentalModel": "Ask: design or build?"}, "invest": {"call": {"kind": "theCall", "situation": "After a quality failure, the FAA caps a factory's output. You are modeling the OEM's next two years.", "prompt": "What decides when the cap lifts?", "options": ["Evidence that the factory's fixes work", "The size of the order backlog", "Pressure from airlines waiting for jets"], "correctIndex": 0, "consequences": ["The FAA reviewed Boeing's lines before allowing 42.", "Demand doesn't satisfy a safety regulator.", "Airlines want planes, but the regulator decides on quality."], "explanation": "The cap lifts when the regulator is satisfied with production quality, not when customers complain."}, "proReasoning": "Investors model a cap's end from quality milestones, not demand. That is why it lasted until October 2025.", "commonMistake": "Assuming customer pressure shortens a safety cap.", "mentalModel": "Quality, not demand, lifts the cap."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your startup's sensor goes inside an airliner's cabin. You've shown the design works.", "prompt": "What else do you need before selling at scale?", "options": ["A famous airline as your first customer", "Approval to produce it consistently", "Nothing beyond the design approval"], "correctIndex": 1, "consequences": ["Fame doesn't replace approval.", "Each unit must match the approved design, so production needs approval too.", "A good design is not enough when every unit must be built to it."], "explanation": "Approving a design and approving its production are separate steps. Both are part of the product in aerospace."}, "proReasoning": "Founders budget for both approvals from day one. Making one good unit is the start; making every unit the same is the business.", "commonMistake": "Planning for design approval and forgetting production.", "mentalModel": "Approve the design, then the factory."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks whether the 737 MAX 9 is badly designed, given the door plug blowout.", "prompt": "What's the fairest answer?", "options": ["Yes, the door plug's design was the cause", "Planes like it can never be built safely", "The fault was in how that one plane was built"], "correctIndex": 2, "consequences": ["The NTSB pointed to bolts left out, not to the design.", "Flying stays very safe because both design and build are checked.", "Four bolts were missing, and even one would have held the plug."], "explanation": "The design held up: even one bolt would have kept the plug in. The build left all four out."}, "proReasoning": "Separate design flaws from build flaws. They have different causes, fixes and approvals.", "commonMistake": "Blaming the design for a missing step on the line.", "mentalModel": "Design flaw or build flaw: ask which."}}}$ml$::jsonb, ARRAY['handwritten-v1']::text[]),
($ml$e2ba56db-5bd2-5c1c-be27-5f67012fba9d$ml$::uuid, $ml$aerospace$ml$, 6, 1, $ml${"id": "aerospace-d6-c1", "title": "6,000 jets, fixed in days", "lessonTitle": "One flaw, hundreds of grounded jets", "slot": 1, "type": "apply", "brief": {"headline": "On November 28, 2025, Airbus told airlines to fix about 6,000 A320-family jets before their next flight. By December 1, fewer than 100 still needed the work.", "kicker": "Apply the lesson: why did this flaw clear in days, not months?", "fullText": "After a JetBlue A320 incident on October 30, 2025, Airbus found that intense solar radiation could corrupt data critical to the flight controls, in a computer called the ELAC. About 6,000 jets, over half the world's A320-family fleet, needed a change before their next flight.\n\nFor about two thirds of them, the fix was to load a previous software version, a brief job. Hundreds needed hardware changes that could take weeks. By December 1, Airbus said fewer than 100 aircraft were still waiting.\n\nCompare the Pratt & Whitney powder flaw: metal parts had to come off and go through crowded repair shops, and jets sat for months.", "sources": [{"url": "https://www.thenationalnews.com/news/us/2025/11/28/airbus-issues-major-a320-recall-after-flight-control-incident/", "label": "The National, Airbus A320 recall, Nov 2025"}, {"url": "https://www.thenationalnews.com/business/aviation/2025/12/01/airbus-says-most-of-its-6000-a320-jets-modified-after-software-issue", "label": "The National, most A320 jets modified, Dec 2025"}, {"url": "https://gazette.com/?p=1137908", "label": "Reuters via The Gazette, RTX engine issue, Sept 2023"}]}, "evidence": {"kind": "sortSignal", "prompt": "Which flaw does each fact describe?", "buckets": ["A320 software fix", "Pratt powder flaw"], "items": [{"text": "The fix had to be done before the next flight", "bucket": 0}, {"text": "Triggered by intense solar radiation", "bucket": 0}, {"text": "Most jets cleared within days", "bucket": 0}, {"text": "Engines came off the wing for inspection", "bucket": 1}, {"text": "Repairs estimated at up to 300 days", "bucket": 1}, {"text": "Caused by a contaminant from 2015", "bucket": 1}], "explanation": "A software rollback can be done at the gate. Metal parts need shop capacity, and that's where months disappear."}, "numbers": {"kind": "numberSense", "prompt": "About 6,000 jets needed the fix, and by December 1 fewer than 100 remained. Roughly what share was done?", "min": 0, "max": 100, "value": 98, "unit": "%", "tolerance": 0.04, "explanation": "Over 98% in about three days. Software at the gate moves fast; engines in a shop do not."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You're on an airline's operations team the day Airbus orders the fix before each jet's next flight.", "prompt": "What do you do first?", "options": ["Keep flying until the next routine check", "Sort jets by software or hardware fix", "Ground the whole fleet for a month"], "correctIndex": 1, "consequences": ["The fix was required before the next flight.", "Software jets go back fast, and hardware jets need planning.", "Most jets need only a brief fix, so a month is a huge overreaction."], "explanation": "Two thirds needed a quick software change. Sorting the fleet first lets most jets fly again fast."}, "proReasoning": "Operations pros triage first: which jets are quick fixes, which need parts. That keeps most of the schedule flying.", "commonMistake": "Treating every affected jet the same.", "mentalModel": "Triage before you ground."}, "invest": {"call": {"kind": "theCall", "situation": "Two fleet-wide flaws: one fixed by a software change at the gate, one needing engines pulled for shop repairs.", "prompt": "Which hits airline earnings harder?", "options": ["The software change", "Both equal if the jet count matches", "The engine shop repairs"], "correctIndex": 2, "consequences": ["Most software fixes cleared within days.", "Fix time, not jet count alone, decides the cost.", "Jets wait months for shop slots, losing revenue every day."], "explanation": "The cost of a flaw is jets times days out of service. Shop repairs keep jets idle for months."}, "proReasoning": "Investors estimate the cost of a grounding as aircraft multiplied by days. The bottleneck in the fix sets the days.", "commonMistake": "Judging a recall by how many planes it touches, not by how long they sit.", "mentalModel": "Cost is jets times days grounded."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your startup is choosing between two products: faster software updates for jets, or more engine repair capacity.", "prompt": "Where did 2023 to 2025 show the bigger bottleneck?", "options": ["Engine repair capacity", "Software updates for jets", "Neither had a real bottleneck"], "correctIndex": 0, "consequences": ["Engine repairs stretched toward 300 days while software fixes took days.", "6,000 jets got their software fix in about three days.", "Hundreds of A320neos sat grounded waiting for engine shops."], "explanation": "Software fixes cleared in days. Engine shops were where jets sat for months."}, "proReasoning": "Founders build where the queue is longest. A bottleneck shows up as time: what keeps planes waiting the longest?", "commonMistake": "Building for the flashiest problem instead of the slowest one.", "mentalModel": "Build where the queue is longest."}, "curiosity": {"call": {"kind": "theCall", "situation": "Your weekend A320 flight is cancelled on November 29, 2025.", "prompt": "What's the likely story?", "options": ["Solar radiation damaged its engines", "It needed a fix before its next flight", "Airbus grounded every A320 for a year"], "correctIndex": 1, "consequences": ["The risk was to flight control data, not the engines.", "Most jets were back within a day or two, and a few needed hardware.", "Most jets flew again within days."], "explanation": "Airbus required the change before each jet's next flight. Most fixes were quick, so the disruption was short."}, "proReasoning": "When a recall hits, ask what the fix is. A software change at the gate is a short delay; parts in a shop can take months.", "commonMistake": "Assuming every recall means long groundings.", "mentalModel": "The fix decides the delay."}}}$ml$::jsonb, ARRAY['handwritten-v1']::text[]),
($ml$e0868011-4202-5b0c-a3b6-08dcb9bce2b2$ml$::uuid, $ml$aerospace$ml$, 6, 2, $ml${"id": "aerospace-d6-c2", "title": "When service becomes the bill", "lessonTitle": "One flaw, hundreds of grounded jets", "slot": 2, "type": "connect", "brief": {"headline": "In September 2023, RTX took a $3 billion charge for the Pratt & Whitney powder flaw. It covered compensation for airlines and extra costs on its long-term maintenance contracts.", "kicker": "Connect day 2 and day 6: the aftermarket can cut both ways.", "fullText": "On day 2 you saw why engine makers sell near cost: parts and service pay for decades, often through long-term maintenance contracts. On day 6 you saw the powder flaw ground hundreds of A320neos.\n\nRTX's $3 billion charge reflected Pratt & Whitney's 51% share of the engine program. It covered estimates of compensation to airlines for fleet disruption, and the added cost of inspections and part replacements under long-term maintenance contracts. RTX put the total hit at $3 billion to $3.5 billion over several years.\n\nWhen an engine maker has promised to maintain the engine, a defect turns the aftermarket from a profit into a bill.", "sources": [{"url": "https://www.sec.gov/Archives/edgar/data/101829/000089882223000025/rtx991-91123.htm", "label": "RTX, powder metal update, Sept 2023"}, {"url": "https://www.janushenderson.com/hub/article/anatomy-of-a-good-company-safran", "label": "Janus Henderson on Safran"}, {"url": "https://gazette.com/?p=1137908", "label": "Reuters via The Gazette, RTX engine issue, Sept 2023"}]}, "evidence": {"kind": "spotFake", "prompt": "One of these is false about the $3 billion charge. Tap it.", "statements": ["It covered compensation for airlines.", "It covered extra costs on maintenance contracts.", "It was paid by the airlines that flew the jets."], "fakeIndex": 2, "explanation": "RTX took the charge. Airlines lost flying, and the engine maker paid for it."}, "numbers": {"kind": "numberSense", "prompt": "RTX put the total hit at $3 billion to $3.5 billion. What is the top of that range, in billions?", "min": 0, "max": 10, "value": 3.5, "unit": "B", "explanation": "Up to $3.5 billion over several years. Promises to maintain the engine turned into costs."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You join Pratt & Whitney's aftermarket team in 2024, as the powder inspections ramp up.", "prompt": "What's the team's main job now?", "options": ["Sell more new engines to those airlines", "Raise prices on the repair work now", "Get engines back to airlines faster"], "correctIndex": 2, "consequences": ["Airlines need their grounded jets flying first.", "Under maintenance contracts, much of the repair cost is Pratt's own.", "Every day an engine waits costs airlines, and Pratt pays part of that."], "explanation": "With compensation and contract costs on its books, Pratt's best lever was shorter repair times."}, "proReasoning": "When your company pays for downtime, the aftermarket team's job becomes speed. Answers that link turnaround time to cost stand out.", "commonMistake": "Thinking the aftermarket is always a profit opportunity.", "mentalModel": "When you pay for downtime, speed is profit."}, "invest": {"call": {"kind": "theCall", "situation": "An engine maker earns much of its profit from long-term service contracts. A fleet-wide defect appears.", "prompt": "Why can the contracts make the defect more costly?", "options": ["They put repair costs on the maker", "They let it bill airlines for repairs", "They end as soon as defects appear"], "correctIndex": 0, "consequences": ["Long-term contracts mean the maker pays for extra inspections and parts.", "Under these contracts, extra repairs are mostly the maker's cost.", "The contracts run for years, defect or not."], "explanation": "Under long-term maintenance contracts, the maker promised to keep the engine running. A defect raises its own costs."}, "proReasoning": "Investors check how aftermarket revenue is earned. Paid-per-repair work profits from problems; long-term contracts absorb them.", "commonMistake": "Assuming more repairs always mean more profit for the engine maker.", "mentalModel": "Know who pays for the repair."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your startup offers a faster inspection method for engine parts made from powdered metal.", "prompt": "Who should feel the most urgency to buy?", "options": ["Airbus, which built the airframes", "Pratt, which pays for the downtime", "Passengers delayed by the groundings"], "correctIndex": 1, "consequences": ["Airbus suffers too, but the engine maker owns the inspections.", "Faster inspections cut Pratt's compensation and contract costs.", "Passengers feel the pain but don't buy inspection tools."], "explanation": "Pratt pays compensation and contract costs while engines wait. Faster inspection saves it money directly."}, "proReasoning": "Founders sell to whoever carries the cost of the problem. Here, the engine maker was paying for every day of delay.", "commonMistake": "Pitching whoever complains loudest instead of whoever pays.", "mentalModel": "Sell to whoever pays for the pain."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks why an engine maker would pay airlines when their jets are grounded for inspections.", "prompt": "What's the best explanation?", "options": ["A law makes every supplier pay the airlines", "Airlines bought the engines on credit", "Its flaw caused it, and it services the engines"], "correctIndex": 2, "consequences": ["No blanket law applies; the flaw and the contracts do.", "Credit terms aren't the reason; the defect and the contracts are.", "RTX's charge covered compensation and extra maintenance costs."], "explanation": "The defect was Pratt's, and many engines were under its long-term maintenance contracts. So it paid."}, "proReasoning": "Follow the promise. Whoever promised to keep something working pays when it does not.", "commonMistake": "Assuming the airline always absorbs the cost of a grounding.", "mentalModel": "Whoever promised the uptime pays for the downtime."}}}$ml$::jsonb, ARRAY['handwritten-v1']::text[]),
($ml$26f9572f-f3cf-5c37-857a-3cb43ba490c0$ml$::uuid, $ml$aerospace$ml$, 6, 3, $ml${"id": "aerospace-d6-c3", "title": "Shop slots and spare engines", "lessonTitle": "One flaw, hundreds of grounded jets", "slot": 3, "type": "decide", "brief": {"headline": "RTX expected the powder flaw to keep an average of 350 jets grounded each year through 2026. Each engine repair, first expected to take 60 days, stretched to as long as 300.", "kicker": "Decide where the scarce thing is: shop slots and spare engines.", "fullText": "When 600 to 700 geared turbofan engines had to come off jets for inspection, the bottleneck moved to the repair shops. Each repair was first expected to take about 60 days; the estimate grew to as long as 300.\n\nRTX expected an average of 350 jets grounded per year through 2026, with as many as 650 idle in the first half of 2024. An engine waiting in the shop is a jet that cannot fly. The scarce things were shop capacity and spare engines.", "sources": [{"url": "https://gazette.com/?p=1137908", "label": "Reuters via The Gazette, RTX engine issue, Sept 2023"}]}, "evidence": {"kind": "buildChain", "prompt": "Follow how the shop queue grounds jets.", "steps": ["Hundreds of engines must come off at once", "Repair shops fill up", "Each repair stretches from 60 days toward 300", "Spare engines run out", "Jets sit grounded waiting for engines"], "explanation": "The flaw created the work. Shop capacity decided how long jets waited."}, "numbers": {"kind": "numberSense", "prompt": "How many jets did RTX expect could be idle at the peak, in the first half of 2024?", "min": 0, "max": 1000, "value": 650, "unit": "jets", "explanation": "As many as 650 at the peak, against an average of 350 a year through 2026."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You're interviewing for an engine shop planning role in 2024. They ask what limits how fast grounded A320neos fly again.", "prompt": "What's your answer?", "options": ["Shop slots and spare engines", "The number of pilots available", "How many new jets Airbus builds"], "correctIndex": 0, "consequences": ["Repairs stretching toward 300 days made shop capacity the limit.", "Pilots were waiting for engines, not the other way round.", "New jets do not bring the grounded ones back."], "explanation": "When hundreds of engines need repair at once, shop capacity and spares decide how fast jets return."}, "proReasoning": "Name the bottleneck and why it binds. In 2024, shop slots and spare engines set the pace, not demand.", "commonMistake": "Naming a symptom, like cancelled flights, instead of the constraint.", "mentalModel": "Find the queue, find the constraint."}, "invest": {"call": {"kind": "theCall", "situation": "You're valuing an engine repair shop in 2024, as A320neo engines queue for inspection.", "prompt": "What makes its next few years strong?", "options": ["Airlines retiring older jets early", "Demand for repairs far above shop capacity", "Fewer engines needing work each year"], "correctIndex": 1, "consequences": ["Short of engines, airlines had reasons to keep older jets flying.", "With repairs stretching toward 300 days, shop capacity is short.", "The work grew; it didn't shrink."], "explanation": "When demand for repair outruns capacity, every existing shop slot becomes valuable."}, "proReasoning": "Investors look for capacity that is scarce relative to demand. In a repair crunch, shops can fill every slot they have.", "commonMistake": "Valuing the shop on normal years when the queue is anything but normal.", "mentalModel": "Scarce capacity earns."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your startup leases spare engines to airlines. A320neo groundings are rising in 2024.", "prompt": "What's your smartest move?", "options": ["Cut lease rates to win new customers", "Wait until the groundings are over", "Line up more spares before the peak"], "correctIndex": 2, "consequences": ["When spares are scarce, you don't need to cut prices.", "By then, the demand you could have served is gone.", "Spares are what airlines need most when engines sit in shops."], "explanation": "When engines wait months in shops, a spare engine keeps a jet flying. Have them ready before the peak."}, "proReasoning": "Founders move early when they see a shortage forming. In a grounding wave, spare engines are what every airline wants.", "commonMistake": "Competing on price in a market that is short of supply.", "mentalModel": "In a shortage, supply beats price."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks why the engines couldn't simply be fixed faster.", "prompt": "What's the real limit?", "options": ["Too few repair shops for so many engines", "Nobody knows how to fix these engines", "The engines were too old to repair"], "correctIndex": 0, "consequences": ["Hundreds of engines hit a fixed number of shop slots at once.", "Shops know how, but there are too many engines at once.", "Many were young engines, and the flaw came from 2015 powder."], "explanation": "Repair takes skilled people, tooling and time. Hundreds of engines at once overwhelmed the shops."}, "proReasoning": "When something takes longer than expected, look for a queue. Capacity, not knowledge, is often the limit.", "commonMistake": "Assuming a fix is slow because nobody knows how.", "mentalModel": "Slow fixes often mean long queues."}}}$ml$::jsonb, ARRAY['handwritten-v1']::text[])
ON CONFLICT (market_id, day, slot) DO UPDATE SET content = EXCLUDED.content, tags = EXCLUDED.tags, updated_at = now();

